// ------------------------------------------------------------------ R7: lo storico
// Lo storico delle conferme di un prodotto della RFQ, dalla prima (R7, EM §9.7): le testate senza i JSON grandi, con il
// nome di chi ha confermato (PE-07: confermato_da_nome) e lo stato di F8 della conferma.
func (q *Queries) ListConfermeStoricoProdotto(ctx context.Context, arg ListConfermeStoricoProdottoParams) ([]ListConfermeStoricoProdottoRow, error) {
	rows, err := q.db.Query(ctx, listConfermeStoricoProdotto, arg.ThreadID, arg.ProdottoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListConfermeStoricoProdottoRow{}
	for rows.Next() {
		var i ListConfermeStoricoProdottoRow
		if err := rows.Scan(
			&i.ConfermaID,
			&i.Numero,
			&i.PrecedenteID,
			&i.Formato,
			&i.SenzaRiepilogoV2,
			&i.FirmaStruttura,
			&i.FirmaAnteprima,
			&i.Contatore,
			&i.ContatoreDati,
			&i.BozzaID,
			&i.BozzaVersione,
			&i.FonteAllegatoID,
			&i.FonteSha256,
			&i.FonteGruppo,
			&i.Origine,
			&i.ImprontaSnapshot,
			&i.MonoPezzo,
			&i.CriterioVerifica,
			&i.Verifica,
			&i.ChiaveIdempotenza,
			&i.ConfermatoDa,
			&i.ConfermatoIl,
			&i.ImportazioneID,
			&i.ImportazioniCitate,
			&i.ConfermatoDaNome,
			&i.ConfermatoDaSigla,
			&i.F8Stato,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

