const listFontiAutorizzateRfq = `-- name: ListFontiAutorizzateRfq :many
SELECT c.componente_id, d.documento_id, d.sha256, prov.allegato_id, (d.sostituito_da IS NOT NULL)::boolean AS superata
  FROM componente c
  JOIN documento d ON d.documento_id = c.step_strutturale_id
  LEFT JOIN LATERAL (
        SELECT p.allegato_id FROM documento_provenienza p
         WHERE p.documento_id = d.documento_id AND p.allegato_id IS NOT NULL
         ORDER BY p.ricevuto_il, p.allegato_id
         LIMIT 1) prov ON true
 WHERE c.thread_id = $1 AND c.step_strutturale_id IS NOT NULL
 ORDER BY c.componente_id
`

type ListFontiAutorizzateRfqRow struct {
	ComponenteID uuid.UUID     `json:"componente_id"`
	DocumentoID  uuid.UUID     `json:"documento_id"`
	Sha256       string        `json:"sha256"`
	AllegatoID   uuid.NullUUID `json:"allegato_id"`
	Superata     bool          `json:"superata"`
}

// La fonte autorizzata di ogni finito della RFQ che ne ha una (componente.step_strutturale_id): il documento, il suo sha256,
// il primo allegato da cui e' arrivato e se il documento e' stato sostituito (versione_corrente.fonte_autorizzata di R1).
func (q *Queries) ListFontiAutorizzateRfq(ctx context.Context, threadID uuid.UUID) ([]ListFontiAutorizzateRfqRow, error) {
	rows, err := q.db.Query(ctx, listFontiAutorizzateRfq, threadID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListFontiAutorizzateRfqRow{}
	for rows.Next() {
		var i ListFontiAutorizzateRfqRow
		if err := rows.Scan(
			&i.ComponenteID,
			&i.DocumentoID,
			&i.Sha256,
			&i.AllegatoID,
			&i.Superata,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

