const listRfqDellaChiave = `-- name: ListRfqDellaChiave :many
SELECT DISTINCT x.thread_id FROM (
    SELECT e.thread_id FROM esito_intento e WHERE e.chiave = $1
    UNION ALL
    SELECT c.thread_id FROM conferma_strutturale c WHERE c.chiave_idempotenza = $1
    UNION ALL
    SELECT f.thread_id FROM file_rfq_evento f WHERE f.chiave_idempotenza = $1
    UNION ALL
    SELECT a.thread_id FROM associazione_evento a WHERE a.chiave_idempotenza = $1
) x
 ORDER BY x.thread_id
`

// Le RFQ in cui una chiave d'intento e' stata usata, in qualunque tabella che la registra (esiti, conferme, eventi dei
// file, eventi delle associazioni): una chiave di un'altra RFQ e' un 422 FUORI_RFQ in R6, mai l'esito di quella RFQ.
func (q *Queries) ListRfqDellaChiave(ctx context.Context, chiave uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listRfqDellaChiave, chiave)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var thread_id uuid.UUID
		if err := rows.Scan(&thread_id); err != nil {
			return nil, err
		}
		items = append(items, thread_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const oraDelDatabase = `-- name: OraDelDatabase :one
SELECT clock_timestamp()::timestamptz AS ora
`

// L'ora del database (clock_timestamp), lo stesso orologio di f8_stato.creato_il: R11 la legge prima di rifare F8, e
// porta a eseguito solo gli stati creati fino a quell'ora.
func (q *Queries) OraDelDatabase(ctx context.Context) (time.Time, error) {
	row := q.db.QueryRow(ctx, oraDelDatabase)
	var ora time.Time
	err := row.Scan(&ora)
	return ora, err
}

const segnaF8Errore = `-- name: SegnaF8Errore :execrows
UPDATE f8_stato SET stato = 'errore', errore = $1, tentativi = tentativi + 1
 WHERE f8_id = $2 AND thread_id = $3 AND stato <> 'eseguito'
`

type SegnaF8ErroreParams struct {
	Errore   pgtype.Text `json:"errore"`
	F8ID     int64       `json:"f8_id"`
	ThreadID uuid.UUID   `json:"thread_id"`
}

// Uno stato di F8 in errore dopo un riallineamento non riuscito, con il testo e un tentativo in piu'.
func (q *Queries) SegnaF8Errore(ctx context.Context, arg SegnaF8ErroreParams) (int64, error) {
	result, err := q.db.Exec(ctx, segnaF8Errore, arg.Errore, arg.F8ID, arg.ThreadID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const segnaF8Eseguito = `-- name: SegnaF8Eseguito :execrows
UPDATE f8_stato SET stato = 'eseguito', errore = NULL, risolto_da = 'riallinea', tentativi = tentativi + 1
 WHERE f8_id = $1 AND thread_id = $2 AND stato <> 'eseguito'
`

type SegnaF8EseguitoParams struct {
	F8ID     int64     `json:"f8_id"`
	ThreadID uuid.UUID `json:"thread_id"`
}

// Uno stato di F8 portato a eseguito (finale) da R11, con un tentativo in piu'.
func (q *Queries) SegnaF8Eseguito(ctx context.Context, arg SegnaF8EseguitoParams) (int64, error) {
	result, err := q.db.Exec(ctx, segnaF8Eseguito, arg.F8ID, arg.ThreadID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
